effect.shader:

 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

      // #define SAMPLE_COUNT 50
      // #define BLUR 0.25
      // #define FALLOFF 3.0

/////////////////////////
 void main ()
 {

     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec3 iMouse = vec3(0.5, 0.5, 0.5);

     /////////////////////////

 	vec4 fragColor;

          vec2 destCoord = acScreenNorm.st;
          vec2 direction = normalize(destCoord - 0.5);
          vec2 velocity = direction * BLUR * pow(length(destCoord - 0.5), FALLOFF);
          float inverseSampleCount = 1.0 / float(SAMPLE_COUNT);

          vec3 accumulator = vec3(0.0);
          vec2 offsetsR = vec2(0.0);
          vec2 offsetsG = vec2(0.0);
          vec2 offsetsB = vec2(0.0);

          for (int i = 0; i < int(SAMPLE_COUNT); i++) {
              accumulator.r += texture2DCv(inputImg.texture, destCoord + offsetsR).r;
              accumulator.g += texture2DCv(inputImg.texture, destCoord + offsetsG).g;
              accumulator.b += texture2DCv(inputImg.texture, destCoord + offsetsB).b;

              offsetsR -= velocity * 1.0 * inverseSampleCount;
              offsetsG -= velocity * 2.0 * inverseSampleCount;
              offsetsB -= velocity * 4.0 * inverseSampleCount;
          }

          fragColor = vec4(accumulator * inverseSampleCount, texColor.a);
          // fragColor = vec4(accumulator * inverseSampleCount, 1.0);

 	    vec4 factor = mix(texColorX,fragColor,1.0);

 	gl_FragColor = mix(texColor, fragColor, alpha);
 	if(OVD) { gl_FragColor *= texColor.a; }
 }
